"""
CloudSage Waste Detection Internal Data Models.
In-memory structures representing findings, telemetry evidence, savings estimations, and detector results.
"""

from dataclasses import dataclass, field
from datetime import datetime
from decimal import Decimal
from typing import Any, Dict, List, Optional
from backend.app.core.enums import Severity, WasteStatus, WasteType


@dataclass
class WasteFinding:
    """Canonical in-memory finding generated by an intelligent waste detector."""
    resource_id: str
    provider: str
    resource_type: str
    waste_type: WasteType
    detector_id: str
    detector_version: str
    finding_title: str
    explanation: str
    severity: Severity
    confidence_score: Decimal
    estimated_monthly_savings: Decimal
    account_id: Optional[str] = None
    resource_name: Optional[str] = None
    currency: str = "USD"
    original_currency: Optional[str] = None
    original_cost: Optional[Decimal] = None
    observation_window_days: int = 7
    data_quality_status: str = "VERIFIED"
    requires_human_review: bool = True
    evidence: Dict[str, Any] = field(default_factory=dict)


@dataclass
class DetectorExecutionResult:
    """Outcome of evaluating a single detector against a target resource."""
    detector_id: str
    resource_id: str
    status: str  # DETECTED, CLEAN, INSUFFICIENT_DATA, ERROR
    finding: Optional[WasteFinding] = None
    message: Optional[str] = None
    evaluation_metadata: Dict[str, Any] = field(default_factory=dict)
